INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "resolved", "resolved_at", "resolution_notes", "created_at") VALUES ('c6dd3f06-9585-4710-8c64-89745334d926', '7bryz6h8llwy6by3xsvxnj', 'el agente no entiende o no puede hacer lo que el estoy pidiendo.', '["Musly Router","Agente de Agendamiento (03-melosmile-agent-appointment)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-07-24T00:39:20.158Z"},{"role":"user","text":"cual es la agenda de la semana?","timestamp":"2026-07-24T00:39:33.774Z"},{"role":"assistant","text":"Aquí tienes la agenda para esta semana:\n\n**Jueves, 23 de julio de 2026:**\n* **16:30:** Paciente General en Clinica Daniel Bustamante con Dr. Shirley García. Motivo: Nueva cita (IA). Estado: Confirmada.\n* **16:45:** Paciente General en Clinica Daniel Bustamante con Dr. Shirley García. Motivo: Nueva cita (IA). Estado: Confirmada.\n\n**Viernes, 24 de julio de 2026:**\n* **15:00:** Test General en Clínica Goya con Dr. Osly Melo. Motivo: Retenedor Fijo. Estado: Pendiente.\n* **16:30:** Munir Manuel Callaos Cardama en Clínica Goya con Dr. Osly Melo. Motivo: Consulta. Estado: Confirmada.","intent":"schedule_appointment","timestamp":"2026-07-24T00:39:38.716Z"},{"role":"user","text":"elimina las citas del jueves 23","timestamp":"2026-07-24T00:40:01.573Z"},{"role":"assistant","text":"No puedo eliminar citas por fecha. Necesito el nombre del paciente o el ID de la cita. Por favor, indícame el nombre del paciente o el ID de la cita para poder ayudarte.","intent":"schedule_appointment","timestamp":"2026-07-24T00:40:04.856Z"},{"role":"user","text":"las de paciente general","timestamp":"2026-07-24T00:40:40.759Z"},{"role":"assistant","text":"Para esta semana, hay 4 citas:\n1. El 23 de julio a las 16:30, Paciente General tiene una cita de Nueva cita (IA) en Clinica Daniel Bustamante con la Dra. Shirley García. Esta cita está confirmada.\n2. El 23 de julio a las 16:45, Paciente General tiene una cita de Nueva cita (IA) en Clinica Daniel Bustamante con la Dra. Shirley García. Esta cita está confirmada.\n3. El 24 de julio a las 15:00, Test General tiene una cita de Retenedor Fijo en Clínica Goya con el Dr. Osly Melo. Esta cita está pendiente.\n4. El 24 de julio a las 16:30, Munir Manuel Callaos Cardama tiene una cita de Consulta en Clínica Goya con el Dr. Osly Melo. Esta cita está confirmada.","intent":"schedule_appointment","timestamp":"2026-07-24T00:40:45.551Z"},{"role":"user","text":"elimina las de Paciente General del jueves 23","timestamp":"2026-07-24T00:41:21.894Z"},{"role":"assistant","text":"Lo siento, ha habido un problema al buscar al paciente. Por favor, inténtalo de nuevo más tarde.","intent":"schedule_appointment","timestamp":"2026-07-24T00:41:37.184Z"}]', true, '2026-07-24T00:44:42.409+00:00', 'Creado Tool_Update_Appointment en n8n y actualizado /api/appointments/update para soportar cancelación/modificación múltiple por nombre de paciente y fecha en lenguaje natural. Mapeados estados enum a español (Cancelada).', '2026-07-24T00:41:56.947+00:00') ON CONFLICT DO NOTHING;
