INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "resolved", "resolved_at", "resolution_notes", "created_at") VALUES ('502a1ba5-6b91-4aa1-b6c3-59f2413505b6', 'aouo0ovlsvf4n1ituijik', 'No reconocio al paciente al quele estaba pidiendo que ejecutara una accion', '["Musly Router","Agente de Agendamiento (03-melosmile-agent-appointment)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-07-24T00:55:59.970Z"},{"role":"user","text":"agenda de la semana","timestamp":"2026-07-24T00:56:06.448Z"},{"role":"assistant","text":"Aquí tienes la agenda para esta semana (del 20 de julio al 26 de julio de 2026):\n\n1.  **24 de julio a las 15:00**: Paciente Test General, motivo Retenedor Fijo, en la Clínica Goya, con el Dr. Osly Melo. El estado es Pendiente.\n2.  **24 de julio a las 16:30**: Paciente Munir Manuel Callaos Cardama, motivo Consulta, en la Clínica Goya, con el Dr. Osly Melo. El estado es Confirmada.","intent":"schedule_appointment","timestamp":"2026-07-24T00:56:11.018Z"},{"role":"user","text":"cambia la de Test General para el sabado a la misma hora","timestamp":"2026-07-24T00:56:41.988Z"},{"role":"assistant","text":"Lo siento, ha habido un error al buscar el paciente \"Test General\". ¿Podrías confirmarme el nombre completo del paciente o si es un nuevo paciente?","intent":"schedule_appointment","timestamp":"2026-07-24T00:56:45.886Z"}]', true, '2026-07-24T00:58:32.317+00:00', 'Implementado algoritmo de puntuación por relevancia (exactness scoring) en /api/patients/search y /api/appointments/update. Test General ya se distingue al 100% de Paciente General. Además se añadió soporte para días relacionales en español (sábado, domingo).', '2026-07-24T00:57:53.462+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "resolved", "resolved_at", "resolution_notes", "created_at") VALUES ('2dd5e9ea-a052-4698-b11e-1fbde4b3930b', 'nyptzweoffakq921qf7md', 'Le ha costado seguir las instrucciones que se le pide', '["Musly Router","Agente General / QA (01-melosmile-agent-qa)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-07-24T01:00:04.865Z"},{"role":"user","text":"agenda de la semana","timestamp":"2026-07-24T01:00:11.270Z"},{"role":"assistant","text":"Aquí tienes la agenda para esta semana (2026-07-20 al 2026-07-26):\n\n*   **24 de julio de 2026 a las 16:30**: Cita de Munir Manuel Callaos Cardama para una Consulta en la Clínica Goya. Estado: Confirmada.\n*   **25 de julio de 2026 a las 15:00**: Cita de Test General para un Retenedor Fijo en la Clínica Goya. Estado: Pendiente.","intent":"schedule_appointment","timestamp":"2026-07-24T01:00:18.822Z"},{"role":"user","text":"cambia la de Test General a las 12:00","timestamp":"2026-07-24T01:00:48.181Z"},{"role":"assistant","text":"Para poder cambiar la cita, necesito saber la fecha de la cita y el nombre completo del paciente. ¿Me puedes proporcionar esa información, por favor?","intent":"schedule_appointment","timestamp":"2026-07-24T01:00:51.049Z"},{"role":"user","text":"Test General a las 12:00 del sabado","timestamp":"2026-07-24T01:01:11.448Z"},{"role":"assistant","text":"Necesito que me especifiques el día y el mes del sábado para poder agendar la cita.","intent":"schedule_appointment","timestamp":"2026-07-24T01:01:14.149Z"},{"role":"user","text":"el mismo dia a las 12:00","timestamp":"2026-07-24T01:01:38.548Z"},{"role":"assistant","text":"Necesito el nombre del paciente para poder agendar la cita.","intent":"schedule_appointment","timestamp":"2026-07-24T01:01:40.714Z"},{"role":"user","text":"Test General","timestamp":"2026-07-24T01:01:46.787Z"},{"role":"assistant","text":"No he reconocido bien la petición. Por favor, especifica más detalladamente tu solicitud. ¿Te refieres a alguna de las siguientes opciones: agendar cita, consultar información del paciente, consultar facturación o registrar una nota clínica?","intent":"general_query","timestamp":"2026-07-24T01:01:48.294Z"}]', true, '2026-07-24T01:12:58.381+00:00', 'Añadida regla en Agent_Scheduling para ejecutar inmediatamente Tool_Update_Appointment sin pedir aclaración al recibir órdenes de modificar/mover hora/fecha de una cita recíentemente mencionada o en contexto.', '2026-07-24T01:02:10.273+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "resolved", "resolved_at", "resolution_notes", "created_at") VALUES ('a8bb4098-19db-4c7c-a0ea-32828b93a851', '84515mu6ydjuy0mvkassws', 'Revisar porque no pudo acceder a la informacion solicitada', '["Musly Router","Agente de Agendamiento (03-melosmile-agent-appointment)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-07-28T09:40:43.279Z"},{"role":"user","text":"cuales fueron mis citas de junio en la clinica de daniel?","timestamp":"2026-07-28T09:41:00.382Z"},{"role":"assistant","text":"Parece que hay un problema técnico al intentar acceder a la información de los pacientes. No puedo consultar las citas de Daniel en junio en este momento. Te recomiendo intentar más tarde o, si lo prefieres, puedo ayudarte con otra consulta o solicitud relacionada con citas. ¿Hay algo más en lo que pueda asistirte?","intent":"schedule_appointment","timestamp":"2026-07-28T09:41:09.307Z"}]', true, '2026-09-08T12:04:13.35+00:00', '''No puedo consultar las citas'': mismo bug de tools apuntando a staging. Corregido 08/09/2026 a agenda.melosmile.com + credencial x-api-key actualizada. Verificado E2E en producción.', '2026-07-28T09:41:41.759+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "resolved", "resolved_at", "resolution_notes", "created_at") VALUES ('2a9e9f76-1964-4ec4-90e6-fb1b5f1784e5', '8g38tqfbmhue4b3diqc3tp', 'revisar el porque dio el error', '["Musly Router","Agente Error / Fallback"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-09-03T12:02:46.950Z"},{"role":"user","text":"dime las citas de la semana pasada","timestamp":"2026-09-03T12:03:01.304Z"},{"role":"assistant","text":"El servicio respondió con un error (404). Inténtalo en unos segundos.","intent":"error","timestamp":"2026-09-03T12:03:02.626Z"}]', true, '2026-09-03T12:09:59.623+00:00', 'Causa: N8N_WEBHOOK_BASE_URL no existía en Vercel y caía en fallback n8n.mumaweb.com (404). Solución: Se inyectaron todas las variables de entorno de n8nv2 y VPS en Vercel (Preview, Production, Development) y se corrigieron los fallbacks de código a n8nv2.mumaweb.com.', '2026-09-03T12:03:29.564+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "resolved", "resolved_at", "resolution_notes", "created_at") VALUES ('3a14e6af-59fa-4774-8a37-6f9fa8fc38a9', '57podebevdvp3j83zjk5x9', 'No esta siendo de mucha ayuda esta agente. revisarlo', '["Musly Router","Agente Clínico (02-melosmile-agent-medical-history)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-09-03T12:55:33.995Z"},{"role":"user","text":"telefono de Munir callaos","timestamp":"2026-09-03T12:55:46.838Z"},{"role":"assistant","text":"El sub-agente clínico no puede proporcionar el número de teléfono de Munir Callaos. Su función se limita a datos clínicos. ¿Hay algo sobre el historial médico de Munir Callaos en lo que pueda ayudarte?","intent":"patient_info","timestamp":"2026-09-03T12:55:53.386Z"},{"role":"user","text":"que puedes hacer con ese paciente?","timestamp":"2026-09-03T12:57:50.330Z"},{"role":"assistant","text":"Para poder ayudarte, necesito que me especifiques qué tipo de información necesitas sobre el paciente. ¿Te refieres a su historial clínico, tratamientos, o algún otro dato médico?","intent":"patient_info","timestamp":"2026-09-03T12:57:53.045Z"},{"role":"user","text":"que tratamiento tiene Munir?","timestamp":"2026-09-03T12:58:23.684Z"},{"role":"assistant","text":"Para poder darte información sobre el tratamiento de Munir, necesito que me aclares a qué Munir te refieres. ¿Me puedes proporcionar el nombre completo o algún otro identificador?","intent":"patient_info","timestamp":"2026-09-03T12:58:28.417Z"},{"role":"user","text":"Munir callaos","timestamp":"2026-09-03T12:58:40.510Z"},{"role":"assistant","text":"He consultado al sub-agente clínico sobre el tratamiento de Munir Callaos. El sub-agente clínico me ha respondido que no puede proporcionar información sobre el tratamiento de Munir Callaos. ¿Hay algo más en lo que pueda ayudarte?","intent":"patient_info","timestamp":"2026-09-03T12:58:44.650Z"}]', true, '2026-09-03T13:00:46.793+00:00', 'Resuelto: 1) Sub-Agent Clínico migrado de gemini-2.5-flash a gpt-4o-mini, equipada Tool_Search_Patients y habilitada entrega de teléfono/datos de contacto. 2) Endpoints clinical/summary actualizados con resolución flexible por nombre/PAC-###/UUID y datos de contacto completos. 3) Sub-Agent Agendamiento blindado para forzar Tool_List_Appointments en consultas recientes/pasadas/semana pasada.', '2026-09-03T12:59:15.285+00:00') ON CONFLICT DO NOTHING;
