INSERT INTO public."ai_agent_reports" ("id", "session_id", "user_comment", "participating_agents", "conversation_history", "resolved", "resolved_at", "resolution_notes", "created_at") VALUES ('b659df08-704f-4592-9171-27679ea82b17', 'v3p1e9cmgw7k0o8pek2ud', 'el agente pierde el contexto. Puede ser un tema relacionada con la de memoria del agente o el contexto que no lo sigue.', '["Musly Router","Agente de Agendamiento (03-melosmile-agent-appointment)"]', '[{"role":"assistant","text":"Hola 👋 Soy Musly, tu asistente IA. Puedo agendar citas, consultar la agenda del día, gestionar pacientes y facturación. ¿En qué te ayudo hoy?","intent":"general_query","timestamp":"2026-07-24T01:10:17.978Z"},{"role":"user","text":"citas para el sabado","timestamp":"2026-07-24T01:10:28.664Z"},{"role":"assistant","text":"Hay una cita para el sábado 25 de julio de 2026 a las 15:00 de Test General en la Clínica Goya, para un Retenedor Fijo.","intent":"schedule_appointment","timestamp":"2026-07-24T01:10:40.576Z"},{"role":"user","text":"cambia esa cita para las 12:00","timestamp":"2026-07-24T01:11:33.244Z"},{"role":"assistant","text":"No he podido identificar la cita a la que te refieres. ¿Me puedes indicar el nombre del paciente?","intent":"schedule_appointment","timestamp":"2026-07-24T01:11:40.890Z"}]', true, '2026-09-09T10:09:02.749+00:00', 'VALIDADO E2E 2026-09-09: contexto largo Musly supera criterio de éxito en staging (staging.melosmile.com). Fixes aplicados: limite history a 30, fallback con historial DB real (dbLoadedHistory), migracion 20260908_add_conversation_context con purga de tests. Desplegado en produccion (agenda.melosmile.com) con merge 9d188e4. Sesion de prueba test-e2e-internal-f5-1788947813030: respuesta correcta "El paciente con el que estabamos conversando es Munir Callaos."', '2026-07-24T01:12:37.194+00:00') ON CONFLICT DO NOTHING;
